  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "明确区分逻辑通信身份、设备映射、容量图、块身份和完成责任；说明估算输入、输出及净荷字节与时间单位。动机和模型适用边界充分。",
      "evidence": [
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "逻辑块身份与物理地址不能混同；地址被复用后，旧完成记录不能放行新对象。"
        },
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "输出是每个阶段的边流量、端点需求、驻留检查和下界，不是对 NCCL 实际算法选择的断言。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "共同操作描述、顺序、物理可达性、容量、浮点契约和缓冲代次均有解释。NCCL、verbs 与 GPUDirect 的关键陈述符合给定固定文档；传输完成、GPU 消费和物理回收边界明确，未将取消等同于 DMA 停止。",
      "evidence": [
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "group calls 只组织提交，不修复不匹配的通信顺序。"
        },
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "浮点归约的算法等价不等于逐位一致。"
        },
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "读者最后使用结束后才复用；失败或取消后保留在途保护"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "提供了两段 pseudocode 和阶段依赖不变量，但 PRICE_COLLECTIVE 未交付候选到阶段及块状态的实际展开规则；RING_COST 的非均匀分块分支随后仍执行平均块长循环，不能完成其声明的输入范围。",
      "evidence": [
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "初始化阶段 DAG：每个阶段只消费前驱阶段已完成的块"
        },
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "若 n 不能被 P 均匀分块：使用实际块长列表，不用单一 n/P 代替\nb←n/P"
        }
      ]
    },
    "cost": {
      "assessment": "partial",
      "reason": "均匀 ring 的轮次、发送账和两个数值算例正确，六类成本及重叠边界清楚；但定价算法没有使用已定义的共享资源组，且非均匀块成本未落实，无法兑现半双工、共享容量和剩余容量输出。",
      "evidence": [
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "若半双工或共享同一上行，必须把两个方向放入同一共享组"
        },
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "w_p←α_p+max(max_a load_a, max_r out_r, max_r in_r)"
        },
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "网络字节减少不等于 HBM 事务、归约 kernel、packing 和同步成本消失。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "消息大小、rank 数、拓扑、并行方式和关键路径改变后，分别说明保留的数学与身份契约、重估的成本及缩小或放弃候选的条件。选择被明确限定为条件化推导。",
      "evidence": [
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "如果它拖慢关键消费者或超出容量，应缩小或放弃聚合。"
        },
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "拓扑改变后，保留集合操作的数学结果契约，重新建立路径、rank 映射和完成代次"
        }
      ]
    },
    "diagnosis": {
      "assessment": "partial",
      "reason": "诊断表具有竞争解释、控制变量和修正预测，设备验证边界也正确；但随章检查宣称覆盖非均匀容量，实际脚本不接收异构容量，且方向测试没有接入定价算法，不能支撑当前检查范围声明。",
      "evidence": [
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "均匀合成快而真实慢，支持分布或桶长问题；两者都慢更像切容量或同步问题"
        },
        {
          "path": "knowledge/hardware/topology-parallelism.md",
          "quote": "独立枚举 ring 的轮次和字节，核对均匀与非均匀容量的下界"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-HW-002-R1-001",
      "criterion": "cost",
      "evidence": "正文定义“κ 把共享同一物理资源的弧分组”，但 PRICE_COLLECTIVE 第 6 步只计算“w_p←α_p+max(max_a load_a, max_r out_r, max_r in_r)”，没有共享组容量或服务需求项。",
      "impact": "两条各传 100 字节、各标 100 字节/秒但共享同一半双工资源的反向弧，在端点收发独立的模型中会得到 1 秒，而共享资源需要至少 2 秒。1 秒仍可作为较弱下界，但算法没有兑现正文要求的共享资源约束，也无法据此给出可靠的共享占用或剩余容量。",
      "blocking": true,
      "required_revision": "定义共享组的容量或资源服务系数，明确同一流跨组内多弧时怎样计实际资源使用，将组服务需求纳入阶段预算与占用输出。让半双工与全双工对照通过同一个定价路径计算，验证共享约束实际生效。"
    },
    {
      "id": "K-HW-002-R1-002",
      "criterion": "algorithm",
      "evidence": "PRICE_COLLECTIVE 第 3 步为“按 S 生成逻辑块：key、源 rank、块号、偏移、字节数、版本”，随后直接“初始化阶段 DAG”；第 4 步读取“owner←b 在 p 开始时的事实所有者”，没有说明这些阶段、消费者及更新后的块从何产生。",
      "impact": "输入 S 仅被描述为 ring、树或分层候选，读者仍需自行补写核心展开算法。尤其 reduce-scatter 每轮产生的部分归约块，其贡献集合、持有者和后继消费者没有状态更新规则，无法独立恢复 flows 或核对是否漏项、重复累计。",
      "blocking": true,
      "required_revision": "明确 S 的数据契约。可将输入收窄为已经展开、带块生产与消费记录的阶段 DAG，并交付本章 ring 候选生成该 DAG 的规则；说明每轮发送块索引、接收归约或复制、版本与持有状态更新、最终完成条件。其他候选可明确仅作成本讨论，无须全部实现。"
    },
    {
      "id": "K-HW-002-R1-003",
      "criterion": "algorithm",
      "evidence": "RING_COST 写道“若 n 不能被 P 均匀分块：使用实际块长列表，不用单一 n/P 代替”，但随后仍执行“b←n/P”和“T←T+max_r (b/B_{r→succ(r)})”。",
      "impact": "非均匀分块分支没有改变循环的数据。设 P=2、n=3 字节，实际块长为 [2,1]，α=0、两条独立有向弧带宽均为 1 字节/秒；两个同步轮次各需 2 秒，总计 4 秒，现有平均块长循环却得到 3 秒。脚本使用 Fraction 接受分数字节，也不会发现该偏差。",
      "blocking": true,
      "required_revision": "为每轮每个 rank 指定实际发送块并使用对应块长计算最大服务时间；发送账按 rank 累计。或者明确限定算法只接受可均分的合法元素块，对其他输入拒绝，并删除其已支持非均匀分块的声明。"
    },
    {
      "id": "K-HW-002-R1-004",
      "criterion": "diagnosis",
      "evidence": "正文宣称“核对均匀与非均匀容量的下界”；脚本 ring_cost 和 ring_cost_loop 都仅接收单个 beta，check_ring_formula 只比较 P=4 的均匀公式与同一公式的循环累加。half_duplex_time 是独立求和函数，没有调用 PRICE_COLLECTIVE 的弧或共享组聚合。",
      "impact": "实际执行成功只支持已列出的标量算术和局部容量函数，不能证明异构容量、实际 ring 块调度或共享组定价正确；当前测试恰好绕过了上述算法缺口。",
      "blocking": true,
      "required_revision": "使检查说明与实际覆盖一致。对修订后的核心算法，用逐轮消息记录及独立字节守恒、资源服务量参考核对结果；覆盖正文保留的异构容量和非均匀块范围，并让忽略共享组或错误使用平均块长的负对照确实被该审计拒绝。"
    }
  ],
  "limitations": [
    "没有目标 GPU、NIC、PCIe 或真实 NCCL 执行证据；有效带宽、启动开销和实际算法选择仍需设备校准。",
    "CPU 算术检查不证明 CUDA 可见性、异步取消、物理排空、真实并发或 Agent 使用效果；正文对此声明清楚，可保留为验证边界。",
    "本次仅依据提供的冻结材料、脚本全文和 actual_preflight 执行记录审查；未自行重跑脚本、重新计算文件哈希或通过文件系统验证链接目标。"
  ],
  "checks": [
    {
      "script": "tools/check_k_hw_002_full.py",
      "args": []
    }
  ],
  "no_checks_reason": "",
  "reading_scope": "完整阅读提供的以下全文，范围为零起点右开字符区间：AGENTS.md [0,567)；docs/knowledge-method.md [0,2251)；docs/knowledge-review.md [0,3016)；knowledge/hardware/topology-parallelism.md [0,12110)；五份来源说明 S-CUDA-TOPOLOGY [0,500)、S-NCCL-COLLECTIVE [0,493)、S-NCCL-GROUP [0,452)、S-RDMA [0,739)、S-GPUDIRECT [0,615)；knowledge/hardware/transport-and-rdma.md [0,4088)；knowledge/system-semantics/distributed-kv-store.md [0,3441)；knowledge/algorithms/routing-and-migration.md [0,3228)；knowledge/workloads/cluster-resource-placement.md [0,3360)；knowledge/system-semantics/deployment-environment.md [0,3882)；四份固定原文 references/S-NCCL-COLLECTIVE/fulltext.txt [0,2570)、references/S-NCCL-GROUP/fulltext.txt [0,5326)、references/S-RDMA/fulltext.txt [0,25147)、references/S-GPUDIRECT/fulltext.txt [0,55368)。完整阅读 candidate.test_script 所提供的脚本及 author_notes、actual_preflight。相关章节仅阅读提供的摘录：parallelism.md [0,6877)、[12000,14567)；disaggregated-serving.md [0,4000)、[8000,10561)、[16000,18883)；collective-ordering.md [0,1631)、[12000,19813)；moe-routing.md [0,5444)、[8000,12000)。CUDA 原文仅阅读所供摘录：[4000,8000)、[16000,20000)、[36000,40000)、[68000,88000)、[96000,100000)、[124000,128000)、[156000,164000)、[204000,208000)、[280000,292000)、[308000,316000)、[340000,348000)、[396000,396151)、[500000,504000)、[516000,524000)、[528000,532000)、[544000,548000)、[676000,680000)、[688000,692000)、[732000,736000)、[748000,756000)、[764000,768000)、[772000,780000)、[792000,796000)、[800000,808000)、[852000,856000)、[928000,932000)、[948000,952000)、[1048000,1052000)、[1100000,1112000)。摘录文件未列入 documents，未声称完整阅读其原件；未读取上游实现源码。",
  "test_assessment": "提供的 actual_preflight 记录显示：绑定脚本在 remote_bwrap 中由 Python 3.12 以隔离参数实际执行，退出码为 0，无 stderr、无超时；脚本哈希与要求一致。这是提供记录中的执行结果，并非本审阅者亲自重跑。作者备注明确说作者当轮未执行，因此不能把后续 preflight 写成作者已执行。逐项检查脚本后，均匀 ring 的 24 MiB 发送账、615.9375 微秒和 30.286102294921875 微秒设定值正确；覆盖了 n=0、P=1、部分非法参数、单向缺弧和简单双工算术。ring_cost_loop 仅展开相同的轮数与平均块长公式，没有模拟块身份、逐轮传递或归约状态，不能作为这些机制的独立参考。共享边负对照实际得到正确求和 2 秒、错误逐流最大值 1 秒，并以断言检测到低估；它有效检验单一共享边的容量求和，但不检验 PRICE_COLLECTIVE 的共享组实现。脚本不存在异构带宽、实际不均匀块、阶段 DAG、容量峰值或块所有者更新检查。方向函数的通过也不能补足定价算法未使用 κ 的问题。上述缺口均属于正文当前已声明的算法与检查范围；设备可见性和物理回收未测则已明确声明，不据此另增设备验收要求。"
}
